    "designCases.goproHero13.result1": "A cohesive advertising presentation of the product \"in action\" + technical details in one format",
    "designCases.goproHero13.result2": "Use of the brand's signature palette and style",
    "designCases.goproHero13.result3": "A format suitable for social media/promo pages",
    "designCases.goproHero13.reviewTitle": "Client review 💬",
    "designCases.goproHero13.reviewText": "The poster turned out exactly as we wanted — the product looks great and all the advantages are visible at once. Thanks for the work!",
    "designCases.goproHero13.reviewAuthor": "Serhii",

