    "designCases.pinkPrFlyers.item2.title": "What We Do flyer",
    "designCases.pinkPrFlyers.item2.caption": "Services overview • Marketing Strategy, Branding, Content Strategy, PR & Visibility, Strategic Consultations",
    "designCases.pinkPrFlyers.item3.title": "Pink Dreams flashmob flyer",
    "designCases.pinkPrFlyers.item3.caption": "Community activation • Call to join the Instagram flashmob • Rules and mechanics",
    "designCases.pinkPrFlyers.finalsTitle": "Final mockups",
    "designCases.pinkPrFlyers.finalsIntro": "Three print-ready flyers — each with its own communication task, all within a single brand system.",
    "designCases.pinkPrFlyers.result1": "A set of 3 print flyers in a single brand style",
    "designCases.pinkPrFlyers.result2": "A clear structure for each flyer matched to its communication goal (announcement, services presentation, community engagement)",
    "designCases.pinkPrFlyers.result3": "The client highlighted the quality and speed of delivery",
